    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '61: A 28-year-old at 37 weeks presents with regular painful contractions. Cervix is 4cm dilated, 80% effaced, and fetus is at -1 station. Diagnosis?', '["False labor", "Preterm labor", "Normal labor (Active phase)", "Late term labor"]', 2, 'Regular contractions with cervical change defines labor. At 4cm, she is in the active phase. (ACOG)'),
    (v_topic_id, '62: Which "Station" indicates the fetal head is at the level of the ischial spines?', '["-2", "-1", "0", "+1"]', 2, 'Station 0 is at the ischial spines. (Williams)'),
    (v_topic_id, '63: The First Stage of labor ends when:', '["Contractions become regular", "The cervix is 10 cm dilated", "The baby is born", "The placenta is delivered"]', 1, 'Stage 1: Dilation; Stage 2: Expulsion; Stage 3: Placenta. (Beckmann)'),
    (v_topic_id, '64: What is the primary movement the fetal head makes to fit through the pelvic inlet during engagement?', '["Extension", "Flexion", "Internal Rotation", "Expulsion"]', 1, 'Flexion allows the smallest diameter (suboccipitobregmatic) to present. (Williams)'),
    (v_topic_id, '65: Internal rotation typically rotates the fetus from a transverse position to which position?', '["Occiput Posterior (OP)", "Occiput Anterior (OA)", "Face first", "Breech"]', 1, 'OA is the most common and favorable position for exit. (Beckmann)'),
    (v_topic_id, '66: Extension of the fetal head occurs during which part of labor?', '["During engagement", "As the head passes under the symphysis pubis", "During internal rotation", "After delivery of the shoulders"]', 1, 'Extension allows the head to emerge from the birth canal. (Williams)'),
    (v_topic_id, '67: What is the term for the head returning to its natural position relative to the shoulders after being born?', '["Restitution (External Rotation)", "Flexion", "Descent", "Molding"]', 0, 'This occurs after the head is born and before the shoulders emerge. (Beckmann)'),
    (v_topic_id, '68: Molding of the fetal head is:', '["A sign of brain damage", "Overlap of cranial bones to fit through the pelvis", "A scalp hematoma", "Always permanent"]', 1, 'Normal adaptation to the birth canal. (Williams)'),
    (v_topic_id, '69: A "Bishop Score" of 9 is most likely associated with:', '["A high risk of C-section", "A high likelihood of successful vaginal induction", "Preterm labor", "Placenta previa"]', 1, 'A high score indicates a "ripe" or favorable cervix. (ACOG)'),
    (v_topic_id, '70: Which of the following is NOT a component of the Bishop Score?', '["Dilation", "Effacement", "Fetal Heart Rate", "Cervical Position", "Station"]', 2, 'Bishop score components: Dilation, Effacement, Station, Consistency, Position. (Beckmann)'),
    (v_topic_id, '71: What is the "Friedman Curve" used to assess?', '["Fetal growth", "Progress of labor (dilation over time)", "Maternal blood pressure", "Postpartum hemorrhage risk"]', 1, 'Traditional tool for mapping labor progress. (Williams)'),
    (v_topic_id, '72: "Arrest of Dilation" in the active phase is traditionally defined as no cervical change for how many hours with adequate contractions?', '["1 hour", "2 hours", "4 hours (or 6 hours with oxytocin)", "24 hours"]', 2, 'Modern guidelines (ACOG) suggest 4-6 hours for arrest. (ACOG)'),
    (v_topic_id, '73: A 30-year-old G1P0 at 39 weeks has a BP of 150/95 on two occasions 4 hours apart. She has 2+ proteinuria. Diagnosis?', '["Gestational HTN", "Pre-eclampsia", "Chronic HTN", "Eclampsia"]', 1, 'New HTN + Proteinuria after 20 weeks = Pre-eclampsia. (ACOG)'),
    (v_topic_id, '74: What is the definitive treatment for Pre-eclampsia at 37 weeks?', '["Bed rest", "Magnesium sulfate only", "Antihypertensives", "Delivery"]', 3, 'Delivery is the only cure. (Williams)'),
    (v_topic_id, '75: Why is Magnesium Sulfate administered during labor for a patient with pre-eclampsia?', '["To lower blood pressure", "To prevent seizures (eclampsia)", "To speed up labor", "To protect the baby''s heart"]', 1, 'Magnesium is for seizure prophylaxis, not BP control. (Beckmann)'),
    (v_topic_id, '76: What is the first sign of Magnesium Toxicity?', '["Respiratory depression", "Loss of deep tendon reflexes (Patellar)", "Cardiac arrest", "Decreased urine output"]', 1, 'Loss of DTRs occurs at 7-10 mEq/L. (Williams)'),
    (v_topic_id, '77: What is the antidote for Magnesium Toxicity?', '["Naloxone", "Protamine sulfate", "Calcium Gluconate", "Vitamin K"]', 2, '10% Calcium Gluconate IV. (ACOG)'),
    (v_topic_id, '78: A pre-eclamptic patient has a BP of 170/110. Which medication is appropriate for acute BP control?', '["Magnesium", "Labetalol or Hydralazine", "Lisinopril", "Furosemide"]', 1, 'IV Labetalol, Hydralazine, or Nifedipine are used for acute HTN. (ACOG)'),
    (v_topic_id, '79: "HELLP Syndrome" includes Hemolysis, Elevated Liver enzymes, and:', '["High lipids", "Low Platelets", "High hemoglobin", "Low glucose"]', 1, 'Hemolysis, Elevated Liver enzymes, Low Platelets. (Williams)'),
    (v_topic_id, '80: A pregnant woman has a seizure at 36 weeks in the setting of HTN. Diagnosis?', '["Epilepsy", "Eclampsia", "Stroke", "Syncope"]', 1, 'Seizure in pre-eclampsia is Eclampsia. (Beckmann)'),
    (v_topic_id, '81: What is the primary risk of Gestational Diabetes (GDM) to the fetus?', '["Congenital heart defects", "Macrosomia and shoulder dystocia", "Oligohydramnios", "Turner Syndrome"]', 1, 'Fetal hyperinsulinemia leads to excessive growth. (Williams)'),
    (v_topic_id, '82: Unlike pre-gestational diabetes, Gestational Diabetes (GDM) is NOT typically associated with:', '["High birth weight", "Congenital malformations", "Hypoglycemia in the neonate", "Polycythemia"]', 1, 'GDM starts after organogenesis; malformations are usually due to poor control in early 1st trimester (pre-existing DM). (Beckmann)'),
    (v_topic_id, '83: First-line management for GDM after diagnosis?', '["Insulin", "Metformin", "Dietary modification and exercise", "Immediate delivery"]', 2, 'Most GDM is diet-controlled. (ACOG)'),
    (v_topic_id, '84: A woman at 38 weeks has a fundal height of 42 cm. Ultrasound estimated fetal weight (EFW) is 4800g. Primary concern during delivery?', '["Placenta previa", "Shoulder dystocia", "Breech presentation", "Preterm labor"]', 1, 'Macrosomia is the #1 risk factor for shoulder dystocia. (Williams)'),
    (v_topic_id, '85: The "McRoberts Maneuver" and "Suprapubic Pressure" are used to manage:', '["Breech delivery", "Shoulder dystocia", "Postpartum hemorrhage", "Uterine inversion"]', 1, 'These are the first-line maneuvers for shoulder dystocia. (ACOG)'),
    (v_topic_id, '86: A woman with GDM should have which test 6-12 weeks postpartum?', '["Repeat GCT", "75g 2-hour Oral Glucose Tolerance Test (OGTT)", "Hemoglobin A1c", "No follow up needed"]', 1, 'To screen for development of Type 2 Diabetes. (ACOG)'),
    (v_topic_id, '87: What is the most common cause of "Late-trimester" vaginal bleeding?', '["Vaginitis", "Placenta Previa and Placental Abruption", "Cervical cancer", "Polyps"]', 1, 'These are the "must-not-miss" causes of bleeding. (Beckmann)'),
    (v_topic_id, '88: Painful vaginal bleeding with uterine tenderness and frequent contractions at 34 weeks. Diagnosis?', '["Placenta previa", "Placental abruption", "Vasa previa", "Normal labor"]', 1, 'Abruption is usually painful; previa is painless. (Williams)'),
    (v_topic_id, '89: What is the most common risk factor for Placental Abruption?', '["Diabetes", "Hypertension (Chronic or Gestational)", "Multiple gestation", "Advanced age"]', 1, 'HTN is the strongest risk factor. (Beckmann)'),
    (v_topic_id, '90: Ultrasound is excellent for diagnosing Previa, but may miss what percentage of Abruptions?', '["1%", "10%", "Up to 50% or more", "None"]', 2, 'Abruption is a clinical diagnosis; US is not sensitive for retroplacental clots. (Williams)'),
    (v_topic_id, '91: Diagnosis of "Placenta Previa" requires:', '["Painful bleeding", "Ultrasound showing placenta covering the internal os", "Speculum exam only", "Blood in the urine"]', 1, 'US is the diagnostic tool of choice. (ACOG)'),
    (v_topic_id, '92: "Vasa Previa" is a condition where:', '["The placenta covers the os", "Fetal vessels cross the internal os unprotected by placenta or cord", "The cord is short", "The placenta is stuck to the muscle"]', 1, 'Associated with high fetal mortality if membranes rupture. (Beckmann)'),
    (v_topic_id, '93: "Placenta Accreta" involves invasion of the placenta into which layer?', '["Amniotic membrane", "Superficial myometrium (due to absent decidua basalis)", "Serosa of the uterus", "Bladder wall"]', 1, 'Accreta: to myometrium; Increta: into; Percreta: through. (Williams)'),
    (v_topic_id, '94: What is the most significant risk factor for Placenta Accreta?', '["Smoking", "Prior Cesarean section and co-existing Placenta Previa", "HTN", "GDM"]', 1, 'Risk increases with the number of prior C-sections. (ACOG)'),
    (v_topic_id, '95: A woman at 30 weeks has regular contractions and cervical change. Diagnosis?', '["False labor", "Preterm labor", "Term labor", "Incompetent cervix"]', 1, 'Labor before 37 weeks is preterm. (ACOG)'),
    (v_topic_id, '96: "Tocolytic" medications (like Nifedipine or Indomethacin) are used in preterm labor to:', '["Stop labor for the rest of the pregnancy", "Delay delivery for 48 hours to allow for steroid administration", "Induce lung maturity directly", "Treat infection"]', 1, 'They buy time for steroids and transport. (Williams)'),
    (v_topic_id, '97: Why is Betamethasone (steroids) given in preterm labor?', '["To treat maternal HTN", "To accelerate fetal lung maturity and prevent RDS", "To stop contractions", "To prevent hemorrhage"]', 1, 'Steroids stimulate surfactant production. (ACOG)'),
    (v_topic_id, '98: Magnesium Sulfate is given for "Neuroprotection" in very preterm deliveries (< 32 weeks) to reduce the risk of:', '["Cerebral Palsy", "Blindness", "Heart defects", "Renal failure"]', 0, 'Proven to reduce the risk of CP in preterm infants. (ACOG)'),
    (v_topic_id, '99: A patient at 38 weeks has "gush of fluid" and Nitrazine positive test but NO contractions. Diagnosis?', '["Labor", "Preterm Labor", "Premature Rupture of Membranes (PROM)", "PPROM"]', 2, 'PROM is rupture before labor at term. (Williams)'),
    (v_topic_id, '100: "Preterm Premature Rupture of Membranes" (PPROM) is rupture:', '["After labor starts", "Before 37 weeks gestation", "Only in twins", "After 42 weeks"]', 1, 'Rupture before term AND before labor. (Beckmann)'),
    (v_topic_id, '101: What is the primary maternal risk after rupture of membranes for a prolonged period?', '["Diabetes", "Chorioamnionitis (Intra-amniotic infection)", "Abruption", "Pre-eclampsia"]', 1, 'Bacteria ascend into the uterine cavity. (ACOG)'),
    (v_topic_id, '102: Clinical signs of Chorioamnionitis include maternal fever, uterine tenderness, and:', '["Fetal bradycardia", "Fetal tachycardia and foul-smelling fluid", "High blood pressure", "Rash"]', 1, 'Fetal tachycardia is often the first sign. (Williams)'),
    (v_topic_id, '103: Management of Chorioamnionitis?', '["Expectant management", "Antibiotics and prompt delivery (Induction)", "Immediate C-section only", "Tocolytics"]', 1, 'Infection is an indication for delivery, not necessarily C-section. (ACOG)'),
    (v_topic_id, '104: "Post-term" pregnancy is defined as pregnancy lasting at least:', '["40 weeks", "41 weeks", "42 weeks", "43 weeks"]', 2, '>= 42 0/7 weeks. (Williams)'),
    (v_topic_id, '105: What is the most common reason for a post-term pregnancy?', '["Placental issues", "Fetal anomalies", "Inaccurate dating (incorrect LMP)", "Maternal obesity"]', 2, 'Dating error is #1. (Beckmann)'),
    (v_topic_id, '106: Post-term pregnancies are at increased risk for "Dysmaturity Syndrome" and:', '["Oligohydramnios and Meconium aspiration", "Polyhydramnios", "Hydrops", "Placenta previa"]', 0, 'Placental function declines after 42 weeks. (Williams)'),
    (v_topic_id, '107: What is the "Gold Standard" for monitoring a post-term patient who is not yet induced?', '["NST and Amniotic Fluid Index (Modified BPP) twice weekly", "Daily ultrasounds", "Kick counts only", "No monitoring"]', 0, 'Monitoring fluid is critical. (ACOG)'),
    (v_topic_id, '108: A woman at 38 weeks is found to have "Intrauterine Growth Restriction" (IUGR), EFW < 10th percentile. Most common cause?', '["Genetic syndrome", "Uteroplacental insufficiency", "Gestational diabetes", "Eating too much"]', 1, 'Poor placental perfusion is the leading cause. (Williams)'),
    (v_topic_id, '109: "Symmetric" IUGR (head and body both small) often suggests:', '["Late pregnancy HTN", "Early pregnancy insult (infection or aneuploidy)", "Normal variant", "Smoking"]', 1, 'Occurs early in pregnancy. Asymmetric (Head-sparing) occurs later. (Beckmann)'),
    (v_topic_id, '110: Which Doppler study is used to assess placental resistance and fetal well-being in IUGR?', '["Uterine artery", "Umbilical Artery Doppler", "MCA Doppler", "Renal Doppler"]', 1, 'High resistance or reversed end-diastolic flow is concerning. (ACOG)'),
    (v_topic_id, '111: A "Polyhydramnios" diagnosis (AFI > 24 cm) should prompt a check for:', '["Maternal HTN", "Maternal Diabetes and Fetal structural anomalies", "Fetal renal agenesis", "Smoking"]', 1, 'GDM and GI/Neuromuscular anomalies (swallowing) are causes. (Williams)'),
    (v_topic_id, '112: The "Triple Screen" and "Quad Screen" are used to screen for:', '["Diabetes", "Aneuploidy (T21, T18) and NTDs", "Infection", "Pre-eclampsia"]', 1, 'Maternal serum screening. (Beckmann)'),
    (v_topic_id, '113: Which marker is DECREASED in both Trisomy 21 and Trisomy 18?', '["hCG", "AFP", "Inhibin A", "None"]', 1, 'AFP is low in both. (Williams)'),
    (v_topic_id, '114: A woman is "Rh sensitized" if her Anti-D titer is:', '["Negative", "1:2", ">= 1:8 (usually)", "Always positive"]', 2, 'A critical titer is usually 1:8 to 1:32 depending on the lab. (ACOG)'),
    (v_topic_id, '115: What is the primary concern with Rh-alloimmunization?', '["Fetal diabetes", "Fetal anemia and Hydrops Fetalis", "Macrosomia", "Preterm birth"]', 1, 'Maternal antibodies destroy fetal RBCs. (Williams)'),
    (v_topic_id, '116: "Hydrops Fetalis" is defined by fluid in at least how many fetal compartments?', '["1", "2 or more (e.g., ascites, pleural effusion, skin edema)", "Only the head", "All of them"]', 1, 'Sign of severe heart failure/anemia. (Beckmann)'),
    (v_topic_id, '117: Which ultrasound measurement is used to monitor a fetus for anemia?', '["BPD", "Middle Cerebral Artery (MCA) Peak Systolic Velocity", "Femur length", "AC"]', 1, 'High velocity = Thin blood (Anemia). (ACOG)'),
    (v_topic_id, '118: "External Cephalic Version" (ECV) is a procedure to:', '["Turn a breech baby to vertex", "Induce labor", "Stop bleeding", "Deliver the placenta"]', 0, 'Done after 37 weeks to avoid C-section. (ACOG)'),
    (v_topic_id, '119: "Terbutaline" is often used during an ECV or during labor to:', '["Speed up contractions", "Relax the uterus (Tocolysis)", "Lower BP", "Treat infection"]', 1, 'A beta-agonist that relaxes smooth muscle. (Williams)'),
    (v_topic_id, '120: Contraindications to a vaginal birth after Cesarean (VBAC)?', '["One prior low-transverse C-section", "Prior classical (vertical) uterine incision", "Twins", "Epidural use"]', 1, 'High risk of uterine rupture with vertical scars. (ACOG)');
